package com.lemnt.trade.application.executor;
import com.lemnt.trade.application.cmd.TradeOrderCreateCmd;import com.lemnt.trade.domain.gateway.*;import com.lemnt.trade.domain.model.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.math.RoundingMode;import java.util.*;
@Component @RequiredArgsConstructor public class TradeOrderCreateCmdExe {private final MemberLookupGateway members;private final ProductCatalogGateway products;private final TradeOrderGateway orders;
 @Transactional(rollbackFor=Exception.class) public TradeOrder execute(TradeOrderCreateCmd cmd){if(cmd==null||cmd.memberId()==null||cmd.memberId()<=0)throw new IllegalArgumentException("会员ID不合法");if(cmd.items()==null||cmd.items().isEmpty())throw new IllegalArgumentException("订单商品不能为空");MemberSnapshot member=members.findById(cmd.memberId());if(member==null||!Integer.valueOf(1).equals(member.status()))throw new IllegalArgumentException("会员不存在或已禁用");Map<Long,Integer> quantities=new LinkedHashMap<>();for(var i:cmd.items()){if(i==null||i.productId()==null||i.productId()<=0||i.quantity()==null||i.quantity()<=0||i.quantity()>999)throw new IllegalArgumentException("商品或购买数量不合法");quantities.merge(i.productId(),i.quantity(),Integer::sum);}Map<Long,ProductSnapshot> snapshots=new LinkedHashMap<>();for(Long id:quantities.keySet()){ProductSnapshot p=products.findOnShelf(id);if(p==null||p.price()==null||p.price().compareTo(BigDecimal.ZERO)<=0)throw new IllegalArgumentException("商品不存在或已下架: "+id);snapshots.put(id,p);}List<Map.Entry<Long,Integer>> reserved=new ArrayList<>();try{for(var e:quantities.entrySet()){if(!products.reserveStock(e.getKey(),e.getValue()))throw new IllegalStateException("库存不足: "+e.getKey());reserved.add(Map.entry(e.getKey(),e.getValue()));}List<TradeOrderItem> items=new ArrayList<>();BigDecimal total=BigDecimal.ZERO;for(var e:quantities.entrySet()){ProductSnapshot p=snapshots.get(e.getKey());BigDecimal line=p.price().multiply(BigDecimal.valueOf(e.getValue())).setScale(2,RoundingMode.HALF_UP);items.add(new TradeOrderItem(p.id(),p.productCode(),p.name(),p.price().setScale(2,RoundingMode.HALF_UP),e.getValue(),line));total=total.add(line);}String no="TR"+UUID.randomUUID().toString().replace("-","").substring(0,24).toUpperCase();return orders.save(TradeOrder.pendingPayment(no,cmd.memberId(),total.setScale(2,RoundingMode.HALF_UP),items));}catch(RuntimeException ex){for(int i=reserved.size()-1;i>=0;i--){var e=reserved.get(i);try{products.releaseStock(e.getKey(),e.getValue());}catch(RuntimeException compensation){ex.addSuppressed(compensation);}}throw ex;}}
}